// 준비 성과를 소비하지 않는다. 실패해도 승인·동선·차량 지원을 유지해 재시도한다.
public sealed class VenueFinale : MonoBehaviour {
 public enum Phase { Available, Scheduling, Opening, Entrance, Admission, Deposit, Observe, Conversation, Exposed, InteriorEscape, StreetEscape, Boarding, Driving, Debrief, Complete, Failed }
 public static VenueFinale Current{get;private set;} public static bool Active=>Current&&Current.Running;
 public Phase State{get;private set;} public bool Running=>State>=Phase.Scheduling&&State<=Phase.Debrief;
 public bool Completed=>State==Phase.Complete;public bool Cinematic=>State==Phase.Opening||State==Phase.Admission||State==Phase.Exposed||State==Phase.Boarding||State==Phase.Driving||State==Phase.Debrief;
 public MechanicMission preparation;public GameObject interior,ui,pizza,approval,actors;public Transform entryGuard;public Transform entry,inside,deliveryTable,observeStand,target,contact,interiorExit,escapeTurn,carStand,car,door,seat,driver,passenger,driveEnd,safePoint;
 public Transform[] interiorPosts,streetPosts;
 public Transform streetArrival;public Transform[] serviceRoute,alleyRoute;int serviceStep,alleyStep;readonly HashSet<CitizenCombat> subdued=new();public int SubduedCount=>subdued.Count;public bool ExitUnlocked=>SubduedCount>=2;
 public Transform EscapeGoal=>State==Phase.InteriorEscape&&serviceRoute!=null&&serviceStep<serviceRoute.Length?serviceRoute[serviceStep]:State==Phase.StreetEscape&&alleyRoute!=null&&alleyStep<alleyRoute.Length?alleyRoute[alleyStep]:State==Phase.InteriorEscape?interiorExit:turned?carStand:escapeTurn;public Text objective,subtitle,marker;public Image fade;public Camera cinema;
 public AudioSource sound,engine;public AudioClip stamp,alarm,doorOpen,doorClose;
 public float observeSeconds=3,openingSeconds=5,revealSeconds=3.5f,boardingSeconds=3.2f,driveSeconds=6;
 [TextArea(2,6)]public string[] opening={"민기: 오늘은 영업 안 해. 납품 명단, 뒷문, 탈출 차량까지 준비됐어.","민기: 피자는 위장이야. 박진웅이 누구와 거래하는지만 확인해. 총부터 꺼내지는 마.","정비사: 조사해 둔 합류 지점에서 기다릴게. 들키면 골목으로 빠져나와."};
 [TextArea(2,6)]public string[] overheard={"박진웅: 은행 건은 끝났어. 기록과 돈을 따로 움직여. 다음 거래 때 흔적을 지운다.","연락책: 그 배달원들은요? 살아서 도시로 들어왔다던데.","박진웅: 민기라는 놈부터 찾아. 그놈이 입을 열면 귀찮아져.","나: 민기를 알고 있어… 거래 기록을 옮긴다고 했어.\n민기: 충분해. 더 가까이 가지 말고 빠져나와."};
 [TextArea(2,6)]public string[] closing={"정비사: 고개 숙여! 큰길만 벗어나면 따돌릴 수 있어.","나: 박진웅이 은행 일의 흔적을 지우고 있어. 다음 거래 전에 기록을 찾아야 해.","민기: 살아 돌아온 게 먼저야. 가게에서 정리하자. 이제 다음 표적은 분명해졌어."};
 public float ObservationProgress{get;private set;}public bool IntelSecured{get;private set;}public string FailureReason{get;private set;}public int EventDay{get;private set;}public CitizenCombat[] Enemies=>enemies.Where(e=>e).ToArray();
 readonly List<CitizenCombat> enemies=new();bool locked,oldMove,oldControl,oldLook,insideVenue,reinforced,turned,announced;int line;float entered,noticeUntil;Vector3 carOrigin;Quaternion carRotation;Camera gameplay;PlayerMove move;CameraMove look;Renderer[] hiddenRenderers;bool[] hiddenStates;PhoneController lockedPhone;bool phoneWasEnabled,phoneWasVisible;GameObject hiddenPhone;
 public PlayerCombat Player=>preparation.Player;public DayNightCycle Day=>preparation.preparation.delivery.broker.day;
 public bool Ready=>preparation&&preparation.Completed&&preparation.preparation.Completed&&preparation.preparation.delivery.Completed&&preparation.preparation.delivery.broker.Completed;
 public bool CanStart=>Ready&&!BrokerMission.Active&&!Completed&&!Day.IsTransitioning&&Day.IsNightPreparation&&!StoryTutorial.Active&&!Player.IsDown&&!Player.RiddenBike&&!Player.WaterRescueActive&&!PoliceControl.IsArrestInProgress&&!(preparation.preparation.delivery.broker.orders&&preparation.preparation.delivery.broker.orders.HasActiveOrder);
 void Awake(){Current=this;ui.SetActive(false);cinema.enabled=false;actors.SetActive(false);pizza.SetActive(false);approval.SetActive(false);car.gameObject.SetActive(false);fade.gameObject.SetActive(false);carOrigin=car.position;carRotation=car.rotation;}
 void OnDestroy(){Release();Clean();if(Current==this)Current=null;}
 void OnDisable(){if(locked)Release();}
 public bool Begin(){if(!CanStart)return false;FailureReason="";Clean();IntelSecured=false;ObservationProgress=0;reinforced=turned=false;serviceStep=alleyStep=0;subdued.Clear();
 FindFirstObjectByType<PhoneController>()?.ClosePhone();Day.pcUIPanel.SetActive(false);preparation.ui.SetActive(false);preparation.preparation.ui.SetActive(false);preparation.preparation.delivery.ui.SetActive(false);Cursor.lockState=CursorLockMode.Locked;Cursor.visible=false;
 foreach(var pc in FindObjectsByType<ShopPC>(FindObjectsSortMode.None))if(pc.pcUIPanel==Day.pcUIPanel&&pc.cameraLookScript)pc.cameraLookScript.enabled=true;
 ui.SetActive(true);actors.SetActive(true);car.gameObject.SetActive(true);car.SetPositionAndRotation(carOrigin,carRotation);door.localRotation=Quaternion.identity;passenger.gameObject.SetActive(false);preparation.supportVehicle.gameObject.SetActive(false);driver.gameObject.SetActive(true);pizza.SetActive(true);approval.SetActive(false);
 if(EventDay==0){int previous=Day.currentDay;Day.OnClick_ConfirmClose();Set(Phase.Scheduling);StartCoroutine(Schedule(previous));}else StartOpening();return true;}
 IEnumerator Schedule(int previous){float until=Time.time+120;while(Day.currentDay==previous&&Time.time<until)yield return null;if(!Running)yield break;if(Day.currentDay==previous){Fail("다음 날 전환을 완료하지 못했습니다.");yield break;}while(Day.fadeScreen&&Day.fadeScreen.gameObject.activeSelf)yield return null;Day.EnterNightPreparation();EventDay=Day.currentDay;StartOpening();}
 void StartOpening(){Day.EnterNightPreparation();Set(Phase.Opening);Lock();subtitle.text=string.Join("\n",opening.Where(t=>!t.StartsWith("정비사:")));Shot(entry.position+Vector3.up*3+Vector3.right*6,entry.position+Vector3.up);}
 void Set(Phase value){State=value;entered=Time.time;line=0;}
 void Notice(string message,float seconds=7){subtitle.text=message;noticeUntil=Time.time+seconds;}
 void Lock(){if(locked)return;locked=true;lockedPhone=FindFirstObjectByType<PhoneController>();if(lockedPhone){lockedPhone.ClosePhone();if(lockedPhone.VisualRoot){hiddenPhone=lockedPhone.VisualRoot.gameObject;phoneWasVisible=hiddenPhone.activeSelf;hiddenPhone.SetActive(false);}phoneWasEnabled=lockedPhone.enabled;lockedPhone.enabled=false;}move=Player.GetComponent<PlayerMove>();gameplay=Player.View;look=gameplay.GetComponent<CameraMove>();oldMove=move.enabled;oldControl=move.isControllable;oldLook=look&&look.enabled;move.enabled=false;move.isControllable=false;if(look)look.enabled=false;gameplay.enabled=false;cinema.enabled=true;}
 void Release(){if(hiddenRenderers!=null){for(int i=0;i<hiddenRenderers.Length;i++)if(hiddenRenderers[i])hiddenRenderers[i].forceRenderingOff=hiddenStates[i];hiddenRenderers=null;}if(!locked)return;locked=false;if(hiddenPhone){hiddenPhone.SetActive(phoneWasVisible);hiddenPhone=null;}if(lockedPhone)lockedPhone.enabled=phoneWasEnabled;if(cinema)cinema.enabled=false;if(gameplay)gameplay.enabled=true;if(move){move.enabled=oldMove;move.isControllable=oldControl;}if(look){look.enabled=oldLook;look.SyncViewFromTransform();}if(fade)fade.gameObject.SetActive(false);}
 void Shot(Vector3 position,Vector3 at){cinema.transform.position=position;cinema.transform.LookAt(at);}
 public void PlacePlayer(Transform anchor){var cc=Player.GetComponent<CharacterController>();bool enabled=cc.enabled;cc.enabled=false;Player.transform.SetPositionAndRotation(anchor.position+Vector3.up*(cc.height*.5f-cc.center.y+.08f),anchor.rotation);Player.View.transform.localRotation=Quaternion.identity;cc.enabled=enabled;Player.View.GetComponent<CameraMove>()?.SyncViewFromTransform();Physics.SyncTransforms();}
 bool Near(Transform t,float range=3.2f){if(!Player.CanAct||Vector3.Distance(Player.transform.position,t.position)>range)return false;var from=Player.View.transform.position;var d=t.position+Vector3.up*.7f-from;return !Physics.RaycastAll(from,d.normalized,d.magnitude,~0,QueryTriggerInteraction.Ignore).Any(h=>!h.transform.IsChildOf(Player.transform)&&!h.transform.IsChildOf(t)&&!h.transform.IsChildOf(pizza.transform)&&!h.transform.IsChildOf(car));}
 public bool Interact(){if(!Running||Time.timeScale<=0)return false;
 if(State==Phase.Entrance&&Near(entry)){Set(Phase.Admission);Lock();approval.SetActive(true);approval.transform.position=entryGuard.TransformPoint(new Vector3(0,1.25f,.3f));approval.transform.rotation=entryGuard.rotation;Shot(entryGuard.position+entryGuard.forward*2+Vector3.up*1.7f,entryGuard.position+Vector3.up*1.2f);Notice("경비: 납품 명단 확인했습니다. 피자는 서비스 테이블에 놓고 바로 나오세요.");if(stamp)sound.PlayOneShot(stamp,.4f);return true;}
 if(State==Phase.Deposit&&Near(deliveryTable)){pizza.SetActive(true);pizza.transform.SetPositionAndRotation(deliveryTable.position,deliveryTable.rotation);Set(Phase.Observe);Notice("민기: 저 안쪽, 붉은 넥타이를 맨 사람이 박진웅이야. 거리를 두고 대화를 확인해.");return true;}
 if(State==Phase.Conversation){AdvanceConversation();return true;}
 if(State==Phase.InteriorEscape&&Near(interiorExit)){if(!ExitUnlocked){Notice("출구 봉쇄 · 경비를 2명 제압해 탈출로를 확보하세요. ("+SubduedCount+"/2)");return false;}Clean();insideVenue=false;PlacePlayer(streetArrival?streetArrival:entry);Set(Phase.StreetEscape);Spawn(streetPosts,2);StoryPhoneInbox.Current?.SendFrom("정비사","골목 끝에서 대기 중","차는 합류 지점에 세워 뒀어. 표시된 골목을 따라 조수석으로 와. 바로 출발하자.");return true;}
 if(State==Phase.StreetEscape&&turned&&Near(carStand)){Clean();Set(Phase.Boarding);Lock();TrafficRecovery.Get(Player.gameObject).Protect(boardingSeconds+driveSeconds+10);hiddenRenderers=Player.GetComponentsInChildren<Renderer>(true);hiddenStates=hiddenRenderers.Select(r=>r.forceRenderingOff).ToArray();foreach(var r in hiddenRenderers)r.forceRenderingOff=true;passenger.gameObject.SetActive(true);passenger.position=carStand.position;passenger.rotation=car.rotation;Shot(car.TransformPoint(new Vector3(4,2.2f,3)),car.position+Vector3.up);if(doorOpen)sound.PlayOneShot(doorOpen,.55f);return true;}return false;}
 public bool CanObserve(){if(State!=Phase.Observe||!Player.CanAct)return false;var delta=target.position+Vector3.up*1.4f-Player.View.transform.position;return Vector3.Distance(Player.transform.position,observeStand.position)<3.5f&&Vector3.Dot(Player.View.transform.forward,delta.normalized)>.9f&&!Physics.RaycastAll(Player.View.transform.position,delta.normalized,delta.magnitude,~0,QueryTriggerInteraction.Ignore).Any(h=>!h.transform.IsChildOf(target)&&!h.transform.IsChildOf(Player.transform));}
 public void Observe(bool held,float seconds){if(Time.timeScale<=0)return;if(!held||!CanObserve()){ObservationProgress=0;return;}ObservationProgress+=seconds/Mathf.Max(.5f,observeSeconds);if(ObservationProgress>=1){ObservationProgress=1;Set(Phase.Conversation);ShowConversation();}}
 void ShowConversation(){subtitle.text=overheard[line]+"\n[F] 계속 · [Space] 대화 건너뛰기";}
 public void AdvanceConversation(bool skip=false){if(State!=Phase.Conversation||Time.timeScale<=0||!Player.CanAct)return;line++;if(!skip&&line<overheard.Length){ShowConversation();return;}IntelSecured=true;Set(Phase.Exposed);Lock();Spawn(interiorPosts,2);foreach(var e in enemies)e.ExternalAttackControl=true;Shot(observeStand.position+Vector3.up*1.8f,target.position+Vector3.up*1.3f);Notice("경비: 저 사람, 은행에서 본 놈입니다!\n박진웅: 문 막아. 살아서 나가게 두지 마!\n민기: 들켰어! 준비한 뒷문으로 빠져!");if(alarm)sound.PlayOneShot(alarm,.6f);}
 void Spawn(Transform[] points,int count){foreach(var post in points.Take(count)){var e=Instantiate(preparation.enemyTemplate,post.position,post.rotation,transform);e.missionEnemy=true;e.gameObject.SetActive(true);e.chaseSpeed=4.2f;e.punchCooldown=1.8f;e.Provoke(Player);enemies.Add(e);}}
 void Clean(){foreach(var e in enemies)if(e){e.EndFight();Destroy(e.gameObject);}enemies.Clear();}
 public void SkipCinematic(){if(!Cinematic||Time.timeScale<=0)return;FinishCinematic();}
 void FinishCinematic(){switch(State){case Phase.Opening:Release();Set(Phase.Entrance);StoryPhoneInbox.Current?.SendFrom("정비사","탈출 차량 대기 중","조사해 둔 합류 지점에서 기다릴게. 들키면 서비스 통로와 뒷골목을 거쳐 와. 차량 위치는 목표 표시로 보냈어.");Notice("마지막 배달 · 납품 승인서를 제시하고 서비스 출입구로 입장하세요.");break;
 case Phase.Admission:approval.SetActive(false);insideVenue=true;PlacePlayer(inside);Release();Set(Phase.Deposit);Notice("서비스 테이블에 피자를 놓고 박진웅을 찾으세요.");break;
 case Phase.Exposed:Release();Set(Phase.InteriorEscape);foreach(var e in enemies)if(e)e.ExternalAttackControl=false;Notice("민기: 출구가 봉쇄됐어! 길목의 경비 두 명을 제압하고 서비스 통로로 빠져!");break;
 case Phase.Boarding:door.localRotation=Quaternion.identity;passenger.position=seat.position;passenger.rotation=seat.rotation;if(doorClose)sound.PlayOneShot(doorClose,.6f);Set(Phase.Driving);if(engine)engine.Play();Notice(closing[0]);break;
 case Phase.Driving:car.position=driveEnd.position;fade.gameObject.SetActive(false);if(engine)engine.Stop();Set(Phase.Debrief);Shot(safePoint.position+Vector3.up*3+Vector3.right*4,safePoint.position+Vector3.up);subtitle.text=string.Join("\n",closing.Skip(1));break;
 case Phase.Debrief:PlacePlayer(safePoint);Release();Set(Phase.Complete);CleanupProps();Notice("첫 번째 사건 · 마지막 배달 완료\n박진웅의 다음 거래와 기록 이동 계획 확보",10);StoryPhoneInbox.Current?.Send("첫 번째 사건 완료","살아 돌아왔네. 박진웅이 은행의 흔적을 지우려 한다는 건 확인했어. 다음 목표는 거래 기록이야. 확보한 정보는 미션에 남겨 뒀어.",true);break;}}
 void CleanupProps(){pizza.SetActive(false);approval.SetActive(false);actors.SetActive(false);car.gameObject.SetActive(false);preparation.supportVehicle.gameObject.SetActive(true);if(engine)engine.Stop();}
 public void DeveloperComplete(){if(Completed||State==Phase.Scheduling)return;StopAllCoroutines();Clean();if(Player.RiddenBike)Player.RiddenBike.ExitBike();Release();PlacePlayer(safePoint);insideVenue=false;IntelSecured=true;Set(Phase.Complete);FailureReason="";CleanupProps();ui.SetActive(false);}
 public void Cancel(){if(Running)Fail("작전을 중단했습니다.");}
 public void Fail(string reason){if(!Running)return;StopAllCoroutines();Clean();if(insideVenue&&!Player.IsDown&&!Player.WaterRescueActive&&!PoliceControl.IsArrestInProgress)PlacePlayer(entry);insideVenue=false;Release();CleanupProps();Set(Phase.Failed);FailureReason=reason;Notice("마지막 배달 중단 · "+reason+"\n준비 성과는 유지됩니다. 휴대폰에서 재시도하세요.",10);}
 void Update(){if(Time.timeScale<=0)return;if(!Running){if(Ready&&!Completed&&!announced){announced=true;StoryPhoneInbox.Current?.Send("첫 번째 사건 · 마지막 배달","승인, 동선, 차량이 모두 준비됐어. 휴대폰에서 마지막 배달을 선택하면 다음 날은 영업을 쉬고 행사장에 들어간다. 준비됐을 때 출발하자.",true);}marker.gameObject.SetActive(false);if(Time.time>noticeUntil)ui.SetActive(false);return;}
 if(State==Phase.Scheduling){objective.text="첫 번째 사건 · 행사 당일로 이동";return;}
 if(Player.HitsTaken>=3||Player.WaterRescueActive||PoliceControl.IsArrestInProgress){Fail("작전을 계속할 수 없습니다.");return;}
 if(Cinematic){float elapsed=Time.time-entered;if(State==Phase.Boarding){float t=Mathf.Clamp01(elapsed/boardingSeconds);door.localRotation=Quaternion.Euler(0,-65*Mathf.Sin(Mathf.PI*t),0);passenger.position=Vector3.Lerp(carStand.position,seat.position,Mathf.SmoothStep(0,1,Mathf.InverseLerp(.25f,.8f,t)));}
 if(State==Phase.Driving){float t=Mathf.Clamp01(elapsed/driveSeconds);car.position=Vector3.Lerp(carOrigin,driveEnd.position,t*t);Shot(car.TransformPoint(new Vector3(3,2.4f,-5)),car.position+car.forward*2+Vector3.up);passenger.position=seat.position;foreach(var wheel in car.GetComponentsInChildren<Transform>())if(wheel.name.Contains("Wheel_")&&!wheel.name.Contains("Steering"))wheel.Rotate(Vector3.right,Time.deltaTime*450,Space.Self);if(engine)engine.pitch=Mathf.Lerp(.8f,1.35f,t);float black=Mathf.InverseLerp(.75f,1,t);fade.gameObject.SetActive(black>0);fade.color=new Color(0,0,0,black);}
 float duration=State==Phase.Opening?openingSeconds:State==Phase.Admission?2.5f:State==Phase.Exposed?revealSeconds:State==Phase.Boarding?boardingSeconds:State==Phase.Driving?driveSeconds:7;
 if(PrologueKeyboard.Pressed(Key.Space)||elapsed>=duration)FinishCinematic();objective.text="첫 번째 사건 · 마지막 배달";marker.gameObject.SetActive(false);return;}
 if(PrologueKeyboard.Pressed(Key.F))Interact();if(State==Phase.Conversation&&PrologueKeyboard.Pressed(Key.Space))AdvanceConversation(true);
 if(State==Phase.Observe)Observe(Keyboard.current!=null&&Keyboard.current.fKey.isPressed,Time.deltaTime);
 if(State==Phase.InteriorEscape){foreach(var enemy in enemies)if(enemy&&(enemy.Health<=0||enemy.Npc.IsKnockedDown))subdued.Add(enemy);}
 if(State==Phase.InteriorEscape&&!reinforced&&Vector3.Distance(Player.transform.position,inside.position)<8){reinforced=true;Spawn(interiorPosts.Skip(2).ToArray(),2);Notice("조직원: 서비스 통로 쪽이다!\n민기: 출입구 바로 앞이야. 멈추지 마!");}
 if(State==Phase.InteriorEscape&&serviceRoute!=null&&serviceStep<serviceRoute.Length&&Vector3.Distance(Player.transform.position,serviceRoute[serviceStep].position)<3)serviceStep++;
 if(State==Phase.StreetEscape&&alleyRoute!=null&&alleyStep<alleyRoute.Length&&Vector3.Distance(Player.transform.position,alleyRoute[alleyStep].position)<4)alleyStep++;
 if(State==Phase.StreetEscape&&!turned&&Vector3.Distance(Player.transform.position,escapeTurn.position)<5){turned=true;StoryPhoneInbox.Current?.SendFrom("정비사","차량 위치 확인","네가 보여. 조수석으로 와! 바로 출발한다.");}
 Transform goal=State==Phase.Entrance?entry:State==Phase.Deposit?deliveryTable:State==Phase.Observe||State==Phase.Conversation?observeStand:EscapeGoal;
 string label=State==Phase.Entrance?"납품 출입구":State==Phase.Deposit?"서비스 테이블":State==Phase.Observe||State==Phase.Conversation?"박진웅 관찰":State==Phase.InteriorEscape?(goal==interiorExit?"골목 출구로 이동":goal.name.Contains("Alley")?"뒷골목으로 탈출":"서비스 통로 따라 이동"):turned?"정비사 차량 탑승":"뒷골목으로 탈출";
 objective.text="마지막 배달 · "+label+(State==Phase.InteriorEscape&&!ExitUnlocked?"\n출구 봉쇄 · 경비 제압 "+SubduedCount+" / 2":"")+(State==Phase.Observe?"\n박진웅을 바라보고 [F] 길게 · "+Mathf.RoundToInt(ObservationProgress*100)+"%":State==Phase.Conversation?"":(State==Phase.InteriorEscape&&goal!=interiorExit)||(State==Phase.StreetEscape&&!turned)?"":"\n[F] 상호작용");marker.gameObject.SetActive(true);StoryTargetDiamond.Place(marker,Player.View,(State==Phase.Observe&&Vector3.Distance(Player.transform.position,observeStand.position)<3.5f)?target.position+Vector3.up*2:goal.position+Vector3.up,Player.transform.position,label);if(State==Phase.Conversation)marker.gameObject.SetActive(false);
 if(State!=Phase.Conversation&&Time.time>noticeUntil)subtitle.text="";
 }
 void LateUpdate(){if(!Running)return;if(State==Phase.Entrance||State==Phase.Deposit){pizza.SetActive(!Player.RiddenBike);pizza.transform.SetPositionAndRotation(Player.View.transform.TransformPoint(new Vector3(-.27f,-.35f,.65f)),Player.View.transform.rotation);}if(State==Phase.Exposed){var d=Player.transform.position-target.position;d.y=0;if(d.sqrMagnitude>.1f)target.rotation=Quaternion.RotateTowards(target.rotation,Quaternion.LookRotation(d),120*Time.deltaTime);}Sit(driver);if(State==Phase.Driving||(State==Phase.Boarding&&Time.time-entered>boardingSeconds*.7f))Sit(passenger);}
 static void Sit(Transform actor){var a=actor.GetComponentInChildren<Animator>();if(!a||!a.isHuman)return;foreach(var b in new[]{HumanBodyBones.LeftUpperLeg,HumanBodyBones.RightUpperLeg}){var t=a.GetBoneTransform(b);if(t)t.localRotation*=Quaternion.Euler(-75,0,0);}foreach(var b in new[]{HumanBodyBones.LeftLowerLeg,HumanBodyBones.RightLowerLeg}){var t=a.GetBoneTransform(b);if(t)t.localRotation*=Quaternion.Euler(85,0,0);}}
}
}
